import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"38、【睽】 兑下离上","description":"周易阐真 - 38、【睽】 兑下离上","frontmatter":{"title":"38、【睽】 兑下离上","description":"周易阐真 - 38、【睽】 兑下离上"},"headers":[],"relativePath":"zh/classics/chanzhen/039.md","filePath":"zh/classics/chanzhen/039.md"}'),s={name:"zh/classics/chanzhen/039.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：睽，火动而上，泽动而下。二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽而其事同也。男女睽而其志通也。万物睽而其事类也，睽之时用大矣哉！</p></blockquote><h1 id="_38、【睽】-兑下离上" tabindex="-1">38、【睽】 兑下离上 <a class="header-anchor" href="#_38、【睽】-兑下离上" aria-label="Permalink to “38、【睽】 兑下离上”">​</a></h1><p>初九：悔亡。丧马勿逐，自复。见恶人，无咎。</p><p>九二：遇主于巷，无咎。</p><p>六三：见舆曳其牛，掣其人，天且劓。无初有终。</p><p>九四：睽孤。遇元夫，交孚，厉，无咎。</p><p>六五：悔亡，厥宗噬肤，往何咎？</p><p>上九：睽孤。见豕负涂，载鬼一车。先张之弧，后说之弧。匪寇婚媾，往遇雨则吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：上火下泽，睽。君子以同而异。</p><p>睽者，彼此不合也。上离火，下兑泽，是上火下泽也。火性上炎，泽水下润，火在上而不能熏泽，泽在下而不能济火，火泽同处，而异其性，睽之象也，</p><p>君子有见于此，知修道者不可不同乎人，而亦不可过同乎人。不同，则惊愚骇俗，取人嫌疑；过同，则随风扬波，落于尘情。以是同中而有异焉。效泽之浸物，混俗和光，物来顺应，方圆不拘，而无物不同；法火之照物，邪正分明，应物不迷，内有主宰，而操守大异。外同而内不同，内异而外不异。故能大同乎人，而亦大异乎人。外同者，依世法也；内异者，修道法也。所谓“修行混俗且和光，圆即圆兮方即方，显晦逆从人莫测，教人争得见行藏”者，是也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>曳，以制反。掣，音彻。弧，音胡。说，音脱。</p><p>睽者，彼此相违之义。卦德上离明，下兑悦，悦生于内，明用于外，悦非所悦，明非所明，悦明不当，故谓睽。此阴阳相隔，和缓调理之卦，承上明夷而来。明夷者，真明有昧之义。真明有昧，假明即出，识神用事，顺其所欲，明于外而不明于内，性乱命摇，与道相隔，此睽之所由来也。然睽则睽矣，又有致合之道，特以明虽在外，若能虚其心，可以返明于内；欲虽起内，若能实其腹，可以扫欲于外。明返欲扫，神定情忘，则阴阳隔碍潜通，睽者亦可以致合，故小事吉也。</p><p>小事者，阴之事。人心用事已久，道心埋没，大事已去，今欲致合，必先去人心而后生道心，道心复后，大事方吉。正在睽中，求其人心不坏，其事足矣。安敢望其大事之吉乎？试就小事吉者论之。</p><p>初九，在睽之初，道心方去，人心方来，若能刚而守正，不为人心所惑，道心自复，有悔者可以悔亡，如丧马勿逐自复也。然必见恶人无咎者，恶人即人心，人心俱有五贼，足以败道。不见人心，不知五贼作祸，见人心而顺其所欲，渐次导引，五贼不得张狂，所以避害耳。此济睽于方睽之时也。</p><p>九二，当阴阳正睽之时，邪气盛而正气弱，道心未易相遇。然刚以柔用，从小道中进步，借人心生道心，如遇主于巷，本有咎者，即能无咎。此济睽于正盛之时也。</p><p>六三，愚而自用，顺其所欲，如舆曳而牛掣也。不悦于内而悦于外，未得于彼，早失于己，如天头而劓鼻也。如此之人，务外伤内，认假失真，到头一着，穷无所归，始悔自错，故无初有终也。但不能悔于初，而悔于终，悔之无益。此不睽而自致其睽也。</p><p>九四，阳在阴中，道心为人心所陷，人心惟危，道心惟微，孤阳无依，是睽孤也。然道心虽微，若能敏而好学，不耻下问，交孚抱道之君子，彼此资益，人心日去，道心日增，久之人心化，道心存，阴阳混合，孤者可以不孤，有咎者可以无咎。此以尊交卑、能济其睽也。</p><p>六五，柔顺虚心，居二阳之中，既明其我家纯阴，又明其他家有阳，虚人心而求道心，本有悔者，而悔可以亡矣。</p><p>夫道心者，人心之宗厥，取道心之宗，点化人心之假，如噬肤之易，以是往而行道，有何睽之咎乎?此以虚求实、能济其睽也。</p><p>上九，处睽之极，道心埋没已久，人不反顾，是睽孤也。道心埋没，人心用事，习染成性，疑虑百出，如豕负涂，载鬼一车矣。若欲复道心，须先明人心，但明之贵于见之，见豕见鬼，实见的人心为害甚大。既能见的，即能明的，先不明而用心，如先张之弧也；后能明而复道心，如后说之弧也。无人心而不见道心，无道心而难知人心，借人心复道心。</p><p>人心虽罪之魁，亦功之首，匪寇而实婚媾也。人心既见，道心即复，于是虚人心，振道心，往而济睽，则阴阳和合，如遇其雨，洗去一切旧染之污，仍是当年圆成无亏之物，其吉为何如乎！此睽终必合，乘时而济睽也。</p><p>六爻俱有睽而致合之道，仅得免其阴阳不睽，而不能阴阳有济，故《彖》曰：“小事吉。”然小事能吉，大事即能吉，睽终而合，阴阳相通，至此而求，大事未有不致吉者。修道者，可不先求其小事之吉乎？</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
